class Shan():
    def __init__(self):
        self.shan = &quot;山&quot;
    def init(self, it):
        print(f&quot;{self.shan}上有座{it}, &quot;)

class Miao():
    def __init__(self):
        self.miao = &quot;庙&quot;
    def init(self, it):
        print(f&quot;{self.miao}里有个{it}, &quot;)

class Lao_He_Shang():
    def __init__(self):
        self.lao_he_shang = &quot;老和尚&quot;
    def init(self, it):
        print(f&quot;{self.lao_he_shang}对{it}说, &quot;)

class Xiao_He_Shang():
    def __init__(self):
        self.xiao_he_shang = &quot;小和尚&quot;

